types.BreadcrumbItem:
interface BreadcrumbItem {
  label: string;
  disabled?: boolean;
  onClick?: () => void;
}

types.ButtonProps:
interface ButtonProps extends BaseProps {
  variant?: ButtonVariant;
  size?: "sm" | "default" | "lg";
  disabled?: boolean;
  control?: Control;
  onClick?: () => void;
  onHover?: (hovered: boolean) => void;
}

types.CarouselItem:
interface CarouselItem {
  value: string;
  content: Child;
  label?: string;
}

types.ChartDatum:
interface ChartDatum {
  label: string;
  value: number;
  color?: string;
}

types.ComboboxOption:
interface ComboboxOption {
  value: string;
  label: string;
  keywords?: readonly string[];
  disabled?: boolean;
}

types.CommandItem:
interface CommandItem {
  value: string;
  label: string;
  keywords?: readonly string[];
  icon?: IconName;
  group?: string;
  shortcut?: string;
  disabled?: boolean;
}

types.DataGridColumn:
interface DataGridColumn<T> {
  key: string;
  header: Child;
  value?: (row: T, index: number) => unknown;
  render?: (row: T, index: number) => Child;
  width?: Style["width"];
  align?: Style["align"];
  sortable?: boolean;
  searchable?: boolean;
  compare?: (a: T, b: T) => number;
}

types.DataGridSort:
interface DataGridSort {
  column: string;
  direction: DataGridSortDirection;
}

types.DropdownMenuItem:
interface DropdownMenuItem {
  value: string;
  label: string;
  icon?: IconName;
  shortcut?: string;
  disabled?: boolean;
  checked?: boolean;
}

types.ImageBytesSource:
interface ImageBytesSource {
  /** Encoded PNG, JPEG, WebP or SVG bytes. */
  bytes: Uint8Array;
  mediaType?: string;
  /** Stable key can reduce GPU cache churn when pixels are updated in place. */
  cacheKey?: string;
}

types.ImageRgbaSource:
interface ImageRgbaSource {
  /** Raw RGBA8 pixels in row-major order. */
  rgba: Uint8Array;
  width: number;
  height: number;
  premultiplied?: boolean;
  cacheKey?: string;
}

types.MenubarItem:
interface MenubarItem {
  value: string;
  label: string;
  disabled?: boolean;
  checked?: boolean;
  shortcut?: string;
  onSelect?: () => void;
}

types.MenubarMenu:
interface MenubarMenu {
  value: string;
  label: string;
  disabled?: boolean;
  items: MenubarItem[];
}

types.MotionTransition:
interface MotionTransition {
  /** Duration in milliseconds. Defaults to 200 when omitted. */
  duration?: number;
  /** Delay in milliseconds. Defaults to 0. */
  delay?: number;
  easing?: MotionEasing;
}

types.NavigationMenuItem:
interface NavigationMenuItem {
  value: string;
  label: string;
  disabled?: boolean;
  links?: readonly NavigationMenuLink[];
}

types.NavigationMenuLink:
interface NavigationMenuLink {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
}

types.QuestionnaireQuestion:
interface QuestionnaireQuestion {
  id: string;
  title: string;
  description?: string;
  type: "text" | "single" | "multiple";
  options?: readonly RadioOption[];
  required?: boolean;
  placeholder?: string;
}

types.SidebarItem:
interface SidebarItem {
  value: string;
  label: string;
  icon?: IconName;
  disabled?: boolean;
  badge?: Child;
}

types.SvgNode:
type SvgNode =
  | readonly [SvgElementName, SvgAttributes]
  | readonly [SvgElementName, SvgAttributes, readonly SvgNode[]];

types.TableColumn:
interface TableColumn<T> {
  key: string;
  header: Child;
  accessor?: keyof T | ((row: T, index: number) => Child);
  render?: (row: T, index: number) => Child;
  width?: Style["width"];
  align?: Style["align"];
}

types.ToastAction:
interface ToastAction {
  label: string;
  onClick: () => void;
}

types.ToastItem:
interface ToastItem {
  id: string;
  title: string;
  description?: string;
  variant?: ToastVariant;
  action?: ToastAction;
}

types.ToggleGroupItem:
interface ToggleGroupItem {
  value: string;
  label: string;
  content?: Child;
  disabled?: boolean;
}

types.TreeNode:
interface TreeNode<T = unknown> {
  id: string;
  label: string;
  children?: readonly TreeNode<T>[];
  disabled?: boolean;
  icon?: IconName;
  data?: T;
}

types.WindowCloseRequestEvent:
interface WindowCloseRequestEvent {
  readonly defaultPrevented: boolean;
  preventDefault(): void;
}
